function ControlSummary(){const {locale}=useI18n(),c=publicationCopy[locale].control;return <section className="control-summary wrap section-space" id="your-control" data-scene="control" aria-labelledby="control-title"><div className="section-heading"><div><p className="eyebrow">{c.eyebrow}</p><KineticHeading id="control-title" lines={[{text:c.title},{text:c.accent,accent:true}]}/></div><p>{c.intro}</p></div><div className="responsibility-columns">{[[c.system,c.systemItems],[c.user,c.userItems]].map(([title,items],i)=><div key={i}><h3>{title as string}</h3><dl>{(items as string[][]).map(([name,text])=><div key={name}><dt>{name}</dt><dd>{text}</dd></div>)}</dl></div>)}</div><div className="control-boundary"><p>{c.ai}</p><Link to="/project" className="text-link">{c.detail}<Arrow/></Link></div></section>}
function EvidenceLinks(){const {locale}=useI18n(),c=publicationCopy[locale].evidence;return <div className="evidence-links"><header><p className="eyebrow">{c.available}</p><h3>{c.title}</h3><p>{c.copy}</p></header><div className="evidence-grid"><article><h4><External href={PUBLIC_EVIDENCE.tools}>{c.toolsTitle}<Arrow diagonal/></External></h4><p>{c.toolsCopy}</p><p className="evidence-limit">{c.toolLimit}</p></article><article><h4><External href={PUBLIC_EVIDENCE.architecture}>{c.architectureTitle}<Arrow diagonal/></External></h4><p>{c.architectureCopy}</p><p className="evidence-next"><strong>{c.next}</strong>{c.nextCopy}</p></article></div><External href={PUBLIC_EVIDENCE.status} className="text-link">{c.source}<Arrow diagonal/></External></div>}
function ProductOverview(){const {locale}=useI18n(),c=publicationCopy[locale].projectOverview;return <section className="product-overview wrap" aria-labelledby="architecture-title"><p className="eyebrow">{c.eyebrow}</p><KineticHeading id="architecture-title" lines={[{text:c.title,accent:true}]}/><p className="overview-intro">{c.copy}</p><div className="architecture-parts">{c.parts.map(([title,text],i)=><article key={title}><span aria-hidden="true">0{i+1}</span><h3>{title}</h3><p>{text}</p></article>)}</div><div className="ai-boundary"><h3>{c.aiTitle}</h3><p>{c.aiCopy}</p><External href={PUBLIC_EVIDENCE.architecture} className="text-link">{c.source}<Arrow diagonal/></External></div></section
